const searchKnowledgeConversationsVectorBySelf = `-- name: SearchKnowledgeConversationsVectorBySelf :many
SELECT k.conversation_id, k.body, k.closed_at, c.number, c.subject,
    (e.embedding <=> own.embedding)::float8 AS distance
FROM knowledge_conversations me
JOIN knowledge_embeddings own
    ON own.workspace_id = me.workspace_id AND own.model_key = $1 AND own.embed_hash = me.embed_hash
JOIN knowledge_conversations k ON k.workspace_id = me.workspace_id AND k.conversation_id <> me.conversation_id
JOIN conversations c ON c.id = k.conversation_id
JOIN knowledge_embeddings e
    ON e.workspace_id = k.workspace_id AND e.model_key = $1 AND e.embed_hash = k.embed_hash
WHERE me.workspace_id = $2 AND me.conversation_id = $3 AND c.deleted_at IS NULL
  AND dimmi_conversation_visible(
      c.assignee_member_id, c.assignee_team_id, c.inbox_id, $4::text,
      $5::uuid, $6::uuid[], $7::boolean,
      $8::uuid[]
  )
ORDER BY distance, k.conversation_id
LIMIT $9
`

