const searchKnowledgeEmbeddingsANN1024 = `-- name: SearchKnowledgeEmbeddingsANN1024 :many
SELECT e.embed_hash FROM knowledge_embeddings e
WHERE e.dims = 1024 AND e.workspace_id = $1 AND e.model_key = $2
ORDER BY (e.embedding::halfvec(1024)) <=> ($3::halfvec)::halfvec(1024)
LIMIT $4
`

type SearchKnowledgeEmbeddingsANN1024Params struct {
	WorkspaceID ids.UUID            `json:"workspace_id"`
	ModelKey    string              `json:"model_key"`
	Embedding   database.HalfVector `json:"embedding"`
	RowLimit    int32               `json:"row_limit"`
}

// SearchKnowledgeEmbeddingsANN1024 finds the nearest 1024-dimension
// vectors of the model through the HNSW index.
func (q *Queries) SearchKnowledgeEmbeddingsANN1024(ctx context.Context, arg SearchKnowledgeEmbeddingsANN1024Params) ([]string, error) {
	rows, err := q.db.Query(ctx, searchKnowledgeEmbeddingsANN1024,
		arg.WorkspaceID,
		arg.ModelKey,
		arg.Embedding,
		arg.RowLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []string
	for rows.Next() {
		var embed_hash string
		if err := rows.Scan(&embed_hash); err != nil {
			return nil, err
		}
		items = append(items, embed_hash)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

