const setPendingEmbeddingModel = `-- name: SetPendingEmbeddingModel :one
UPDATE knowledge_settings
SET pending_model_key = $1, pending_key_id = $2,
    embeddings_status = CASE WHEN active_model_key IS NULL THEN 'building' ELSE embeddings_status END,
    embeddings_error = NULL, reembed_total = 0, reembed_done = 0, reembed_failed = 0,
    reembed_started_at = $3::timestamptz, updated_at = $3
WHERE workspace_id = $4
RETURNING workspace_id, active_model_key, embedding_key_id, pending_model_key, pending_key_id, previous_model_key, embeddings_status, embeddings_error, reembed_total, reembed_done, reembed_failed, reembed_started_at, switched_at, created_at, updated_at
`

type SetPendingEmbeddingModelParams struct {
	PendingModelKey *string   `json:"pending_model_key"`
	PendingKeyID    *ids.UUID `json:"pending_key_id"`
	Now             time.Time `json:"now"`
	WorkspaceID     ids.UUID  `json:"workspace_id"`
}

// SetPendingEmbeddingModel starts building a model while the active one
// keeps serving searches.
func (q *Queries) SetPendingEmbeddingModel(ctx context.Context, arg SetPendingEmbeddingModelParams) (KnowledgeSetting, error) {
	row := q.db.QueryRow(ctx, setPendingEmbeddingModel,
		arg.PendingModelKey,
		arg.PendingKeyID,
		arg.Now,
		arg.WorkspaceID,
	)
	var i KnowledgeSetting
	err := row.Scan(
		&i.WorkspaceID,
		&i.ActiveModelKey,
		&i.EmbeddingKeyID,
		&i.PendingModelKey,
		&i.PendingKeyID,
		&i.PreviousModelKey,
		&i.EmbeddingsStatus,
		&i.EmbeddingsError,
		&i.ReembedTotal,
		&i.ReembedDone,
		&i.ReembedFailed,
		&i.ReembedStartedAt,
		&i.SwitchedAt,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

const switchEmbeddingModel = `-- name: SwitchEmbeddingModel :exec
UPDATE knowledge_settings
SET previous_model_key = active_model_key, active_model_key = pending_model_key,
    embedding_key_id = pending_key_id, pending_model_key = NULL, pending_key_id = NULL,
    embeddings_status = 'ready', embeddings_error = NULL, switched_at = $1::timestamptz, updated_at = $1
WHERE workspace_id = $2 AND pending_model_key = $3::text
`

type SwitchEmbeddingModelParams struct {
	Now         time.Time `json:"now"`
	WorkspaceID ids.UUID  `json:"workspace_id"`
	ModelKey    string    `json:"model_key"`
}

// SwitchEmbeddingModel makes the fully built pending model the active
// one, keeping the old one's name for the rollback window.
func (q *Queries) SwitchEmbeddingModel(ctx context.Context, arg SwitchEmbeddingModelParams) error {
	_, err := q.db.Exec(ctx, switchEmbeddingModel, arg.Now, arg.WorkspaceID, arg.ModelKey)
	return err
}

