const upsertKnowledgeConversation = `-- name: UpsertKnowledgeConversation :exec
INSERT INTO knowledge_conversations (conversation_id, workspace_id, body, embed_hash, closed_at, updated_at)
VALUES ($1, $2, $3, $4, $5, $6)
ON CONFLICT (conversation_id)
DO UPDATE SET body = EXCLUDED.body, embed_hash = EXCLUDED.embed_hash, closed_at = EXCLUDED.closed_at,
    updated_at = EXCLUDED.updated_at
`

type UpsertKnowledgeConversationParams struct {
	ConversationID ids.UUID  `json:"conversation_id"`
	WorkspaceID    ids.UUID  `json:"workspace_id"`
	Body           string    `json:"body"`
	EmbedHash      string    `json:"embed_hash"`
	ClosedAt       time.Time `json:"closed_at"`
	Now            time.Time `json:"now"`
}

// UpsertKnowledgeConversation stores a closed conversation's text.
func (q *Queries) UpsertKnowledgeConversation(ctx context.Context, arg UpsertKnowledgeConversationParams) error {
	_, err := q.db.Exec(ctx, upsertKnowledgeConversation,
		arg.ConversationID,
		arg.WorkspaceID,
		arg.Body,
		arg.EmbedHash,
		arg.ClosedAt,
		arg.Now,
	)
	return err
}
